-- DarkChaos: percent-based consumables for level 81 and above (generated by tools/balance/gen_consumables.py)
--
-- Five new items, usable from level 81, that restore a share of the maximum instead of a fixed amount:
--   423000 Frontier Healing Potion    20% of maximum health
--   423001 Frontier Mana Potion       24% of maximum mana
--   423002 Dense Frostweave Bandage   32% of the target's maximum health over 8 seconds (First Aid 400)
--   423003 Frontier Rations           4% of maximum health per second for 24 seconds
--   423004 Frontier Springwater       4% of maximum mana per second for 24 seconds
-- The shares are what the stock level-80 items give a level-80 character. Each item is a copy of its stock
-- counterpart (33447, 33448, 34722, 35953, 33445) with a new name, spell, level and price; the stock items
-- are not touched. The spells (920001, 920002, 920003, 920004, 920005) are rows of Spell.dbc and the items need
-- rows in Item.dbc: the server needs both DBC files in place before this file does anything.
--
-- Every vendor on maps 750, 751 that already sells food or drink also sells all five.
-- Re-running gives the same result. Apply to acore_world, then restart the worldserver.

-- Frontier Healing Potion
DROP TEMPORARY TABLE IF EXISTS `dc_tmp_consumable`;
CREATE TEMPORARY TABLE `dc_tmp_consumable` SELECT * FROM `item_template` WHERE `entry` = 33447;
UPDATE `dc_tmp_consumable` SET `entry` = 423000, `name` = 'Frontier Healing Potion', `ItemLevel` = 90, `RequiredLevel` = 81, `BuyPrice` = 60000, `SellPrice` = 15000, `spellid_1` = 920001, `VerifiedBuild` = 0;
REPLACE INTO `item_template` SELECT * FROM `dc_tmp_consumable`;
DROP TEMPORARY TABLE `dc_tmp_consumable`;

-- Frontier Mana Potion
DROP TEMPORARY TABLE IF EXISTS `dc_tmp_consumable`;
CREATE TEMPORARY TABLE `dc_tmp_consumable` SELECT * FROM `item_template` WHERE `entry` = 33448;
UPDATE `dc_tmp_consumable` SET `entry` = 423001, `name` = 'Frontier Mana Potion', `ItemLevel` = 90, `RequiredLevel` = 81, `BuyPrice` = 60000, `SellPrice` = 15000, `spellid_1` = 920002, `VerifiedBuild` = 0;
REPLACE INTO `item_template` SELECT * FROM `dc_tmp_consumable`;
DROP TEMPORARY TABLE `dc_tmp_consumable`;

-- Dense Frostweave Bandage
DROP TEMPORARY TABLE IF EXISTS `dc_tmp_consumable`;
CREATE TEMPORARY TABLE `dc_tmp_consumable` SELECT * FROM `item_template` WHERE `entry` = 34722;
UPDATE `dc_tmp_consumable` SET `entry` = 423002, `name` = 'Dense Frostweave Bandage', `ItemLevel` = 90, `RequiredLevel` = 81, `BuyPrice` = 30000, `SellPrice` = 7500, `spellid_1` = 920003, `VerifiedBuild` = 0;
REPLACE INTO `item_template` SELECT * FROM `dc_tmp_consumable`;
DROP TEMPORARY TABLE `dc_tmp_consumable`;

-- Frontier Rations
DROP TEMPORARY TABLE IF EXISTS `dc_tmp_consumable`;
CREATE TEMPORARY TABLE `dc_tmp_consumable` SELECT * FROM `item_template` WHERE `entry` = 35953;
UPDATE `dc_tmp_consumable` SET `entry` = 423003, `name` = 'Frontier Rations', `ItemLevel` = 90, `RequiredLevel` = 81, `BuyPrice` = 20000, `SellPrice` = 1000, `spellid_1` = 920004, `VerifiedBuild` = 0;
REPLACE INTO `item_template` SELECT * FROM `dc_tmp_consumable`;
DROP TEMPORARY TABLE `dc_tmp_consumable`;

-- Frontier Springwater
DROP TEMPORARY TABLE IF EXISTS `dc_tmp_consumable`;
CREATE TEMPORARY TABLE `dc_tmp_consumable` SELECT * FROM `item_template` WHERE `entry` = 33445;
UPDATE `dc_tmp_consumable` SET `entry` = 423004, `name` = 'Frontier Springwater', `ItemLevel` = 90, `RequiredLevel` = 81, `BuyPrice` = 20000, `SellPrice` = 1000, `spellid_1` = 920005, `VerifiedBuild` = 0;
REPLACE INTO `item_template` SELECT * FROM `dc_tmp_consumable`;
DROP TEMPORARY TABLE `dc_tmp_consumable`;

-- The bandage keeps the Recently Bandaged rule of every other bandage.
DELETE FROM `spell_script_names` WHERE `spell_id` = 920003 AND `ScriptName` = 'spell_gen_bandage';
INSERT INTO `spell_script_names` (`spell_id`, `ScriptName`) VALUES (920003, 'spell_gen_bandage');

-- Vendors
DELETE FROM `npc_vendor` WHERE `item` IN (423000, 423001, 423002, 423003, 423004);
INSERT INTO `npc_vendor` (`entry`, `slot`, `item`, `maxcount`, `incrtime`, `ExtendedCost`, `VerifiedBuild`) SELECT DISTINCT `v`.`entry`, 0, `n`.`entry`, 0, 0, 0, 0 FROM `npc_vendor` AS `v` JOIN `item_template` AS `it` ON `it`.`entry` = `v`.`item` AND `it`.`class` = 0 AND `it`.`subclass` = 5 JOIN `item_template` AS `n` ON `n`.`entry` BETWEEN 423000 AND 423004 WHERE `v`.`entry` IN (SELECT `id` FROM `creature` WHERE `map` IN (750, 751));
